generated_qss:
QMainWindow, QWidget { background-color: #FFFFFF; color: #24292F; font-size: 10pt; }

QGroupBox {
    border: 1px solid #D0D7DE;
    border-radius: 4px;
    margin-top: 8px;
    padding-top: 0px;
    font-weight: bold;
    color: #007CA3;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 8px;
    padding: 0 4px;
}

QTabWidget::pane
{
    border: 1px solid #D0D7DE;
    top: -1px;
}

QTabBar::tab
{
    background-color: #F6F8FA;
    color: #24292F;
    padding: 6px 12px;
    border: 1px solid #D0D7DE;
    border-top-left-radius: 4px;
    border-top-right-radius: 4px;
    min-width: 70px;
}

QTabBar::tab:selected
{
    background-color: #EAEEF2;
    color: #007CA3;
    font-weight: 600;
    margin-bottom: 0px;
}

QTabBar::tab:hover
{
    background-color: #218BFF;
    color: #FFFFFF;
}

QTabBar::tab:!selected
{
    margin-top: 2px;
}

QListWidget { background-color: #F6F8FA; }
QListWidget::item:selected { background-color: #218BFF; color: #FFFFFF; }

QTableView {
    background-color: #F6F8FA;
    alternate-background-color: #FFFFFF;
    color: #24292F;
    gridline-color: #D0D7DE;
    selection-background-color: #EAEEF2;
}
QHeaderView::section {
    background-color: #EAEEF2;
    color: #007CA3;
    border: 1px solid #D0D7DE;
    padding: 3px;
    font-weight: bold;
}
QTableWidget {
    background-color: #F6F8FA;
    color: #24292F;
    gridline-color: #D0D7DE;
}

/* ---- Global input sizing ---------------------------------------------- */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QAbstractSpinBox {
    background-color: #EAEEF2;
    color: #24292F;
    border: 1px solid #D0D7DE;
    border-radius: 3px;
    min-height: 28px;
    padding-top: 4px;
    padding-bottom: 4px;
    padding-left: 4px;
    padding-right: 4px;
}
QComboBox QAbstractItemView {
    background: #EAEEF2;
    color: #24292F;
    selection-background-color: #218BFF;
    selection-color: #FFFFFF;
}
QComboBox QAbstractItemView::item { min-height: 28px; }
QComboBox::drop-down { border: none; min-height: 28px; }

QTextEdit {
    background-color: #F6F8FA;
    color: #24292F;
    border: 1px solid #D0D7DE;
}

QPushButton {
    background-color: #EAEEF2;
    color: #24292F;
    border: 1px solid #D0D7DE;
    border-radius: 4px;
    padding: 5px 10px;
}
QPushButton:hover { background-color: #218BFF; color: #FFFFFF; }
QPushButton:disabled { color: #656D76; border-color: #D0D7DE; }

/* ---- Named action buttons (set via objectName) ------------------------ */
QPushButton#btnConnect    { background-color: #0A7A2A;     color: #FFFFFF; font-weight: bold; }
QPushButton#btnDisconnect { background-color: #CF222E;  color: #FFFFFF; }
QPushButton#btnRead       { background-color: #0A7A2A;        color: #FFFFFF; font-weight: bold; }
QPushButton#btnWrite      { background-color: #0969DA;       color: #FFFFFF; font-weight: bold; }
QPushButton#btnWriteRead  { background-color: #8250DF;  color: #FFFFFF; font-weight: bold; }
QPushButton#btnScan       { background-color: #BC4C00;        color: #FFFFFF; font-weight: bold; }
QPushButton#btnApply      { font-weight: bold; }
QPushButton#btnSpyStart   { background-color: #0A7A2A;     color: #FFFFFF; font-weight: bold; font-size: 13px; padding: 6px; }
QPushButton#btnSpyStop    { background-color: #CF222E;  color: #FFFFFF; font-weight: bold; font-size: 13px; padding: 6px; }

QLabel#specgenSectionHeading {
    font-size: 13pt;
    font-weight: 600;
    color: #24292F;
    margin-top: 8px;
    margin-bottom: 4px;
}

QLabel#noteLabel { color: #9A6700; font-size: 10px; }
QLabel#mutedLabel { color: #656D76; }
/* [XREF: file-picker] validated file-status line colors */
QLabel#statusOk { color: #0A7A2A; }
QLabel#statusError { color: #CF222E; }

QPushButton[saveDirty="true"] {
    background-color: #0A7A2A;
    color: #FFFFFF;
    font-weight: 600;
    border-radius: 3px;
    padding: 4px 12px;
}
QPushButton[saveDirty="true"]:hover { background-color: #0C8F31; }

QStatusBar { background-color: #EAEEF2; color: #24292F; }
QSplitter::handle { background: #D0D7DE; }
QScrollBar:vertical { background: #FFFFFF; width: 10px; }
QScrollBar::handle:vertical { background: #D0D7DE; border-radius: 4px; min-height: 20px; }
QCheckBox { color: #24292F; spacing: 5px; }
QRadioButton { color: #24292F; spacing: 6px; }
QProgressDialog { background-color: #FFFFFF; color: #24292F; }
